// Assemble disjoint floating-sheet G blocks in voltage order without a global sort.
#include "../charge_compiler/json.hpp"
#include "sparse_runs_v2.hpp"
#include <gmpxx.h>
#include <map>
#include <unordered_map>
#include <set>
#include <iostream>
#include <time.h>
using I=long long;using Real=long double;
static double now(){timespec t{};require(clock_gettime(CLOCK_BOOTTIME,&t)==0,"clock");return t.tv_sec+t.tv_nsec*1e-9;}
struct Shape{I nodes=0;std::map<std::pair<I,I>,mpq_class> k;};
struct Field{uint64_t base=0;I nodes=0;};
struct Block{I field=0,shape=0,sheet=0;uint64_t base=0;};
int main(int argc,char**argv){try{
 require(argc==2,"usage: compile_floating_G CONFIG");auto cfg=Json::read(argv[1]);double deadline=cfg.at("deadline_uptime").num();I field_count=cfg.at("global_fields").integer();require(field_count>1&&field_count<100000000,"bounded global fields");std::vector<Field> fields(field_count);std::string line;std::ifstream source(cfg.at("floating_nodes").str());require(bool(source),"floating voltage ranges");uint64_t next=cfg.at("first_floating_voltage").integer();I range_count=0,point_count=0;
 while(std::getline(source,line)){auto row=Json::parse(line);I f=row.at(0).integer(),n=row.at(2).integer();uint64_t base=row.at(1).integer();require(f>0&&f<field_count&&!fields[f].base&&n>0&&base==next,"unique contiguous floating ranges");fields[f]={base,n};next+=n;point_count+=n;range_count++;}require(source.eof()&&next==uint64_t(cfg.at("global_voltage_nodes").integer()),"complete floating voltage suffix");
 std::map<I,Shape> shapes;source=std::ifstream(cfg.at("templates").str());require(bool(source),"floating unit templates");while(std::getline(source,line)){auto row=Json::parse(line);if(row.at("refinement").integer()!=1)continue;I id=row.at("global_template_id").integer();Shape shape;shape.nodes=row.at("points_native_internal").arr().size();require(shape.nodes>=2&&shape.nodes<=4096,"bounded template nodes");for(auto& v:row.at("unit_sheet_stiffness").arr()){I a=v.at(0).integer(),b=v.at(1).integer();mpq_class q(v.at(2).str()+"/"+v.at(3).str());q.canonicalize();require(a>=0&&b>=0&&a<shape.nodes&&b<shape.nodes&&shape.k.emplace(std::pair{a,b},q).second,"unique valid stiffness coefficient");}
  std::vector<mpq_class> sums(shape.nodes);std::vector<std::set<I>> graph(shape.nodes);for(auto&[ij,q]:shape.k){auto[a,b]=ij;require(shape.k.count({b,a})&&shape.k.at({b,a})==q,"symmetric exact floating stiffness");sums[a]+=q;if(a==b)require(q>0,"positive floating diagonal");else{require(q<=0,"nonnegative floating edge conductance");if(q<0)graph[a].insert(b);}}for(auto&q:sums)require(q==0,"exact floating constant nullspace");std::set<I> visited;std::vector<I> pending{0};while(!pending.empty()){I n=pending.back();pending.pop_back();if(!visited.insert(n).second)continue;for(I j:graph[n])pending.push_back(j);}require(I(visited.size())==shape.nodes,"connected floating sheet graph");require(shapes.emplace(id,std::move(shape)).second,"unique refinement-one template");}require(source.eof(),"complete templates");
 std::unordered_map<std::string,I> aliases;auto alias_rows=Json::read(cfg.at("template_aliases").str());for(auto&row:alias_rows.arr())require(aliases.emplace(row.at("local_template_id").str(),row.at("global_template_id").integer()).second,"unique local shape alias");
 I arithmetic_links=0;std::vector<Block> blocks;blocks.reserve(range_count);std::vector<uint8_t> seen(field_count);std::map<std::string,I> materials;for(auto&path:cfg.at("floating_parts").arr()){source=std::ifstream(path.str());require(bool(source),"floating instances");while(std::getline(source,line)){if(blocks.size()%10000==0)require(now()<deadline,"floating G instance deadline");auto row=Json::parse(line);I field=row.at("physical_field_id").integer(),rho=row.at("nominal_sheet_milliohm").integer();require(field>0&&field<field_count&&!seen[field]&&fields[field].base&&rho>0&&rho<1000000000,"unique physical floating instance and positive nominal sheet");for(auto& ref:row.at("arithmetic_bookkeeping_field_ids").arr()){I id=ref.integer();require(id>0&&id<field_count&&!fields[id].base,"arithmetic link must have no voltage range");arithmetic_links++;}I shape=aliases.at(row.at("local_template_id").str());require(shapes.count(shape)&&shapes.at(shape).nodes==fields[field].nodes,"shape and runtime voltage identity");blocks.push_back({field,shape,rho,fields[field].base});seen[field]=1;materials[row.at("native_type").str()]++;}require(source.eof(),"complete instance part");}
 require(I(blocks.size())==range_count&&range_count==cfg.at("expected_instances").integer()&&point_count==cfg.at("expected_floating_nodes").integer(),"complete floating G instance/node coverage");std::sort(blocks.begin(),blocks.end(),[](auto&a,auto&b){return a.base<b.base;});
 std::map<std::pair<I,I>,std::vector<std::pair<uint64_t,Real>>> cached;std::ofstream matrix(cfg.at("matrix").str(),std::ios::binary),ledger(cfg.at("instance_ledger").str());require(bool(matrix)&&bool(ledger),"floating G outputs");sparse::header(matrix,0);uint64_t entries=0,last=0;bool have=false;next=cfg.at("first_floating_voltage").integer();
 for(auto& block:blocks){if(entries%10000==0)require(now()<deadline,"floating G assembly deadline");auto&shape=shapes.at(block.shape);require(block.base==next,"sorted floating block partition");next+=shape.nodes;auto key=std::pair{block.shape,block.sheet};auto found=cached.find(key);if(found==cached.end()){std::vector<std::pair<uint64_t,Real>> k;for(auto&[ij,q]:shape.k){auto[a,b]=ij;if(a>b||q==0)continue;mpq_class conductance=q*1000L/long(block.sheet);Real value=std::stold(conductance.get_num().get_str())/std::stold(conductance.get_den().get_str());require(std::isfinite(value),"finite nominal floating conductance");k.push_back({uint64_t(a)<<32|uint64_t(b),value});}found=cached.emplace(key,std::move(k)).first;}
  for(auto[index,value]:found->second){uint64_t a=block.base+(index>>32),b=block.base+(index&UINT32_MAX),global=a<<32|b;require(!have||global>last,"strict floating block sparse order");sparse::write_record(matrix,{global,value,std::fabs(value),1});last=global;have=true;entries++;}ledger<<Json(Json::Array{block.field,I(block.base),shape.nodes,block.shape,block.sheet}).dump()<<'\n';}
 require(next==uint64_t(cfg.at("global_voltage_nodes").integer()),"complete nominal floating G suffix");matrix.seekp(0);sparse::header(matrix,entries);matrix.close();ledger.close();require(bool(matrix)&&bool(ledger),"floating G outputs closed");Json report=Json::object(),counts=Json::object();for(auto&[material,count]:materials)counts[material]=count;report["floating_instances"]=range_count;report["arithmetic_links_without_states"]=arithmetic_links;report["floating_voltage_nodes"]=point_count;report["upper_conductance_entries"]=I(entries);report["exact_connected_Laplacian_templates"]=I(shapes.size());report["cached_shape_sheet_pairs"]=I(cached.size());report["material_instance_counts"]=counts;report["nominal_conductance_units"]="siemens under pinned milliohm sheet convention";report["exact_template_constant_nullspaces_verified"]=true;report["rounded_matrix_gauge_audit_required"]=true;report["floating_conductors_grounded"]=false;report["material_PVT_qualified"]=false;report["physical_RC_qualified"]=false;report["release_qualified"]=false;std::cout<<report.dump()<<'\n';return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
